"It's Saturday morning.":"Jest sobotni poranek.",
"I want to bake a cake for Mum!":"Chcę upiec ciasto dla mamy!",
"Can I help you?":"Mogę ci pomóc?",
"Yes! We need flour, eggs and sugar.":"Tak! Potrzebujemy mąki, jajek i cukru.",
"Meow!":"Miau!",
"Pus, don't eat the butter!":"Pus, nie jedz masła!",
"Oh no! Flour all over the kitchen!":"O nie! Mąka po całej kuchni!",
"The cake is ready. It's a bit crooked...":"Ciasto gotowe. Jest trochę krzywe…",
"But it smells so good!":"Ale tak ładnie pachnie!",
"Thank you so much, my darlings! This is the best cake in the world!":"Bardzo wam dziękuję, kochani! To najlepsze ciasto na świecie!",
"Meow, meow!":"Miau, miau!",
"Good morning, Leo! Today is your first day at school.":"Dzień dobry, Leo! Dziś twój pierwszy dzień w szkole.",
"I'm a little scared, Mum.":"Trochę się boję, mamo.",
"Hi and welcome! My name is Ingrid. What's your name?":"Cześć i witaj! Nazywam się Ingrid. A ty jak masz na imię?",
"My name is Leo. I come from Ukraine.":"Mam na imię Leo. Pochodzę z Ukrainy.",
"Hi, Leo! Do you want to sit next to me?":"Cześć, Leo! Chcesz usiąść obok mnie?",
"Yes, I'd love to!":"Tak, bardzo chętnie!",
"What is one plus two?":"Ile to jest jeden plus dwa?",
"Three!":"Trzy!",
"You're so clever!":"Jesteś taki mądry!",
"Break time!":"Przerwa!",
"Come on, let's play football!":"Chodź, zagramy w piłkę!",
"How was school?":"Jak było w szkole?",
"Super fun! Nora is my new friend!":"Super! Nora to moja nowa koleżanka!",
"Today we're going for a walk in the forest!":"Dziś idziemy na spacer do lasu!",
"Hooray! I'll bring the basket.":"Hurra! Wezmę koszyk.",
"Look, there's a mushroom!":"Patrz, tam jest grzyb!",
"That mushroom is poisonous. Don't eat it!":"Ten grzyb jest trujący. Nie jedz go!",
"There are lots of blueberries here!":"Tu jest mnóstwo jagód!",
"Yum! They're so sweet!":"Mniam! Są takie słodkie!",
"What was that?":"Co to było?",
"A moose! It's huge!":"Łoś! Jest ogromny!",
"Then it starts to rain.":"Wtedy zaczyna padać.",
"Be quiet. Now we walk home calmly.":"Bądź cicho. Teraz spokojnie idziemy do domu.",
"Now we're going to drink hot cocoa.":"Teraz napijemy się gorącego kakao.",
"That was a lovely walk!":"To był piękny spacer!",
"And we saw a real moose!":"I widzieliśmy prawdziwego łosia!",
"Mia, can you do the shopping for me?":"Mia, zrobisz dla mnie zakupy?",
"Yes! What do you need?":"Tak! Czego potrzebujesz?",
"We need milk, bread and apples. Here are a hundred kroner.":"Potrzebujemy mleka, chleba i jabłek. Masz sto koron.",
"Thanks, Mum!":"Dzięki, mamo!",
"Excuse me, where is the milk?":"Przepraszam, gdzie jest mleko?",
"The milk is over there, by the bread.":"Mleko jest tam, przy chlebie.",
"I'll take six red apples.":"Wezmę sześć czerwonych jabłek.",
"That will be eighty kroner.":"To będzie osiemdziesiąt koron.",
"Here you go, here's a hundred.":"Proszę, tutaj sto.",
"Twenty kroner change. Have a nice day!":"Dwadzieścia koron reszty. Miłego dnia!",
"You're so clever, Mia! Thank you so much.":"Jesteś taka mądra, Mia! Bardzo dziękuję.",
"That was easy!":"To było łatwe!",
"Meow! Milk?":"Miau! Mleko?",
