"A New Friend at School":"Nowy przyjaciel w szkole",
"Good morning! Welcome to our class.":"Dzień dobry! Witamy na naszej lekcji.",
"Hello! Thank you.":"Cześć! Dziękuję.",
"Hi! What is your name?":"Hej! Jak masz na imię?",
"My name is Nora. What is your name?":"Mam na imię Nora. A ty?",
"I am Leo. Nice to meet you!":"Jestem Leo. Miło cię poznać!",
"Nice to meet you too.":"Mnie również miło cię poznać.",
"How old are you?":"Ile masz lat?",
