"Lost in the City":"Zagubiony w mieście",
"Excuse me, could you help me? I think I am lost.":"Przepraszam, czy możesz mi pomóc? Chyba się zgubiłem.",
"Of course. Where do you want to go?":"Oczywiście. Dokąd chcesz iść?",
"I am looking for the city library.":"Szukam miejskiej biblioteki.",
"Go straight on and turn left at the traffic lights.":"Idź prosto i skręć w lewo przy sygnalizacji świetlnej.",
"Then walk past the bus stop. The library is opposite the bank.":"Potem przejdź obok przystanku autobusowego. Biblioteka jest naprzeciwko banku.",
"Is it far from here?":"Czy to daleko stąd?",
"No, it only takes about ten minutes on foot.":"Nie, to tylko około dziesięciu minut piechotą.",
"Great. And is there a café near the library?":"Świetnie. A czy w pobliżu biblioteki jest kawiarnia?",
"Later, Ruslan took the wrong bus.":"Później Rusłan wsiadł do złego autobusu.",
"This bus does not go there. Get off at the next stop and cross the road.":"Ten autobus tam nie jedzie. Wysiądź na następnym przystanku i przejdź przez ulicę.",
"Finally! The library is on the corner, just like you said.":"W końcu! Biblioteka jest na rogu, dokładnie tak jak mówiłeś.",
"Well done! Now you will never get lost again.":"Brawo! Teraz już nigdy się nie zgubisz.",
