"Grammar in real life":"Gramatyka w praktyce",
"What is coding?":"Czym jest programowanie?",
"The school has a robot called Robo. He only follows exact commands, and the children learn that a program is commands in the right order.":"Szkoła ma robota o imieniu Robo. Wykonuje tylko dokładne polecenia, a dzieci uczą się, że program to polecenia we właściwej kolejności.",
"Look, Nora! The school has got a robot.":"Patrz, Nora! Szkoła ma robota.",
"Hi, robot! What is your name?":"Cześć, robocie! Jak masz na imię?",
"Hi! My name is Robo. I do what you tell me.":"Cześć! Mam na imię Robo. Robię to, co mi powiecie.",
"Robo only understands commands. We call that programming.":"Robo rozumie tylko polecenia. To nazywamy programowaniem.",
"What is a command?":"Co to jest polecenie?",
"A command is a short instruction, for example “walk” or “turn”.":"Polecenie to krótka instrukcja, na przykład „idź” albo „obróć się”.",
"Robo, take two steps forward!":"Robo, zrób dwa kroki do przodu!",
"Walking. One, two. Done!":"Idę. Raz, dwa. Gotowe!",
"Robo, make me a pizza!":"Robo, zrób mi pizzę!",
"Error! I do not know the command “pizza”.":"Błąd! Nie znam polecenia „pizza”.",
"A program is many commands in the right order.":"Program to wiele poleceń we właściwej kolejności.",
"So we have to think step by step!":"Czyli musimy myśleć krok po kroku!",
"I want to learn to code!":"Chcę nauczyć się programować!",
"And I want to learn to make pizza.":"A ja chcę nauczyć się robić pizzę.",
"a robot":"robot",
"programming, coding":"programowanie",
"to code":"programować",
"a command":"polecenie",
"a program":"program",
"a message, an instruction":"wiadomość, instrukcja",
"to understand":"rozumieć",
"forward":"do przodu",
"to turn":"obracać się",
"done, finished":"gotowe",
"error; wrong":"błąd; źle",
"to know":"znać",
"an order, a sequence":"kolejność",
"right, correct":"właściwy, poprawny",
"step by step":"krok po kroku",
"The sandwich algorithm":"Algorytm kanapki",
"Leo teaches Robo the robot to make a sandwich. Robo does everything literally, so Leo learns that an algorithm must be exact and in the right order.":"Leo uczy robota Robo robić kanapkę. Robo wykonuje wszystko dosłownie, więc Leo uczy się, że algorytm musi być dokładny i we właściwej kolejności.",
"Dad, I am going to teach Robo to make a sandwich.":"Tato, nauczę Robo robić kanapkę.",
"Then you need an algorithm.":"W takim razie potrzebujesz algorytmu.",
"What is an algorithm?":"Co to jest algorytm?",
"An algorithm is like a recipe: step by step, in the right order.":"Algorytm jest jak przepis: krok po kroku, we właściwej kolejności.",
"Step one: Take the bread. Step two: Put on butter.":"Krok pierwszy: weź chleb. Krok drugi: posmaruj masłem.",
"Butter on … the table? Done!":"Masło na… stół? Zrobione!",
"Ha ha! You have to say exactly what Robo should do.":"Ha ha! Musisz dokładnie powiedzieć, co Robo ma zrobić.",
"New step two: Put butter on the slice of bread!":"Nowy krok drugi: posmaruj kromkę chleba masłem!",
"Step three: Put on cheese. Step four: Give the sandwich to Leo.":"Krok trzeci: połóż ser. Krok czwarty: daj kanapkę Leo.",
"Done! Here you are.":"Zrobione! Proszę bardzo.",
"Mmm! The algorithm works!":"Mmm! Algorytm działa!",
"And remember: the order is important. First butter, then cheese.":"I pamiętaj: kolejność jest ważna. Najpierw masło, potem ser.",
"an algorithm":"algorytm",
"a slice of bread, a sandwich":"kromka chleba, kanapka",
"a cheese":"ser",
"to put on":"położyć na",
"done, carried out":"wykonane",
"important":"ważny",
"then":"potem",
"Repeat! Robo dances":"Powtórz! Robo tańczy",
"Nora wants Robo to dance, but there are too many commands. The teacher shows a loop: “repeat 4 times” — and the program becomes short.":"Nora chce, żeby Robo tańczył, ale poleceń jest za dużo. Nauczycielka pokazuje pętlę: „powtórz 4 razy” – i program staje się krótki.",
"Robo, jump! Clap! Jump! Clap! Jump! Clap!":"Robo, skok! Klaśnij! Skok! Klaśnij! Skok! Klaśnij!",
"Jump. Clap. Jump. Clap …":"Skok. Klaśnięcie. Skok. Klaśnięcie…",
"Phew, that is a lot to write.":"Uff, to dużo pisania.",
"Use a loop! A loop repeats commands.":"Użyj pętli! Pętla powtarza polecenia.",
"Write: repeat four times: jump and clap.":"Napisz: powtórz cztery razy: skok i klaśnięcie.",
"So short!":"Jak krótko!",
"Jump, clap! Jump, clap! Jump, clap! Jump, clap!":"Skok, klask! Skok, klask! Skok, klask! Skok, klask!",
"Robo is dancing!":"Robo tańczy!",
"Can we repeat it a hundred times?":"Możemy powtórzyć to sto razy?",
"Yes. Computers never get tired.":"Tak. Komputery nigdy się nie męczą.",
"But Robo is getting dizzy …":"Ale Robo dostaje zawrotów głowy…",
"Ha ha! We are stopping the loop now.":"Ha ha! Teraz zatrzymujemy pętlę.",
"a loop":"pętla",
"to jump":"skakać",
"to clap":"klaskać",
"a lot":"dużo",
"to use":"używać",
"four times":"cztery razy",
"a hundred":"sto",
"to stop":"zatrzymywać",
"If it rains …":"Jeśli pada deszcz…",
"Robo does not know when to take an umbrella. Leo and Mum write him a rule: if it rains — an umbrella, otherwise — sunglasses.":"Robo nie wie, kiedy brać parasol. Leo i mama piszą mu regułę: jeśli pada – parasol, w przeciwnym razie – okulary przeciwsłoneczne.",
"Robo, we are going out. Bring an umbrella.":"Robo, wychodzimy. Weź parasol.",
"Why? The sun is shining.":"Dlaczego? Świeci słońce.",
"You are right, Robo. We need a rule.":"Masz rację, Robo. Potrzebujemy reguły.",
"If it rains, we take an umbrella.":"Jeśli pada, bierzemy parasol.",
"If it rains, then we take an umbrella. Otherwise we take sunglasses.":"Jeśli pada, to bierzemy parasol. W przeciwnym razie bierzemy okulary przeciwsłoneczne.",
"If … then … otherwise. Understood!":"Jeśli… to… w przeciwnym razie. Zrozumiałem!",
"It is raining. I am taking the umbrella.":"Pada deszcz. Biorę parasol.",
"Good, Robo!":"Brawo, Robo!",
"Now the sun is shining. I am taking sunglasses.":"Teraz świeci słońce. Biorę okulary przeciwsłoneczne.",
"Robo thinks like a computer.":"Robo myśli jak komputer.",
"If I tidy my room, then I get ice cream?":"Jeśli posprzątam pokój, to dostanę lody?",
"Yes! That is a good rule.":"Tak! To dobra reguła.",
"otherwise, else":"w przeciwnym razie",
"an umbrella":"parasol",
"sunglasses":"okulary przeciwsłoneczne",
"the sun is shining":"świeci słońce",
"to go out":"wychodzić",
"to bring":"zabrać ze sobą",
"to be right":"mieć rację",
"understood":"zrozumiałem",
"to think":"myśleć",
"Points in the box":"Punkty w pudełku",
"Nora and Leo make a game: a cat catches fish and gets points. The teacher explains a variable — a box with a name where the computer keeps a number.":"Nora i Leo tworzą grę: kot łapie ryby i zdobywa punkty. Nauczycielka wyjaśnia zmienną – pudełko z nazwą, w którym komputer przechowuje liczbę.",
"We are making a game! Every time the cat catches a fish, we get a point.":"Robimy grę! Za każdym razem, gdy kot złapie rybę, dostajemy punkt.",
"But where will the computer remember the points?":"Ale gdzie komputer zapamięta punkty?",
"In a variable. A variable is like a box with a name.":"W zmiennej. Zmienna jest jak pudełko z nazwą.",
"The box is called “points”. Right now there is zero in the box.":"Pudełko nazywa się „punkty”. Teraz jest w nim zero.",
"The cat catches a fish!":"Kot łapie rybę!",
"Then we write: points equals points plus one.":"Wtedy piszemy: punkty równa się punkty plus jeden.",
