"Find the bug!":"Znajdź błąd!",
"Robo has to reach the star but walks into a wall. The children read the program line by line, find the bug and fix it.":"Robo ma dojść do gwiazdy, ale wchodzi w ścianę. Dzieci czytają program linijka po linijce, znajdują błąd i go poprawiają.",
"Robo has to walk to the star. I have written the program.":"Robo ma dojść do gwiazdy. Napisałem program.",
"I am starting the program now.":"Uruchamiam teraz program.",
"Ouch! I walked straight into the wall.":"Auć! Wszedłem prosto w ścianę.",
"Oops! The program has a bug.":"Ups! Program ma błąd.",
"We call an error in a program a bug.":"Błąd w programie nazywamy bugiem.",
"Finding and fixing the error is called debugging.":"Szukanie i poprawianie błędu to debugowanie.",
"We read the program line by line: forward, forward, right …":"Czytamy program linijka po linijce: do przodu, do przodu, w prawo…",
"There! It should say left, not right.":"Tam! Powinno być w lewo, nie w prawo.",
"Now I will fix the bug and try again.":"Teraz poprawię błąd i spróbuję jeszcze raz.",
"I am at the star! The program works.":"Jestem przy gwieździe! Program działa.",
"All programmers make mistakes. The important thing is to try again.":"Wszyscy programiści popełniają błędy. Najważniejsze, żeby próbować dalej.",
"Mistakes are part of learning!":"Błędy są częścią nauki!",
