"Which language?":"Jaki język?",
"Leo asks Robo which language he speaks. The teacher explains programming languages: Scratch, Python, JavaScript, HTML and CSS, Swift, Kotlin and C#.":"Leo pyta Robo, jakim językiem mówi. Nauczycielka objaśnia języki programowania: Scratch, Python, JavaScript, HTML i CSS, Swift, Kotlin i C#.",
"Robo, which language do you speak? Norwegian?":"Robo, jakim językiem mówisz? Po norwesku?",
"I understand programming languages. There are many!":"Rozumiem języki programowania. Jest ich wiele!",
"Children often start with Scratch. There we move colourful blocks.":"Dzieci często zaczynają od Scratcha. Tam przesuwamy kolorowe bloki.",
"It looks like Lego!":"Wygląda jak klocki Lego!",
"Python is easy to read. It is used for games, data and artificial intelligence.":"Pythona łatwo się czyta. Używa się go do gier, danych i sztucznej inteligencji.",
"Artificial intelligence? Like Robo?":"Sztuczna inteligencja? Jak Robo?",
"HTML builds web pages, and CSS makes them pretty. JavaScript makes them move.":"HTML buduje strony internetowe, a CSS sprawia, że są ładne. JavaScript sprawia, że się ruszają.",
"So the school website is made with them?":"Czyli strona szkoły jest zrobiona w nich?",
