"The class makes a model of the schoolyard. The children learn that a model is a simple copy, that things in a program have properties, and that you draw the plan before the code.":"Klasa robi model szkolnego podwórka. Dzieci uczą się, że model to prosta kopia, że rzeczy w programie mają właściwości i że plan rysuje się przed kodem.",
"Today we are making a model of the schoolyard.":"Dziś robimy model szkolnego podwórka.",
"What is a model?":"Co to jest model?",
"A model is a simple copy of something real. A map is a model too.":"Model to prosta kopia czegoś prawdziwego. Mapa też jest modelem.",
"Like the map in a game!":"Jak mapa w grze!",
"We only draw the important things: the school, the gate and the football pitch.":"Rysujemy tylko to, co ważne: szkołę, bramę i boisko.",
"We do not need to draw every single leaf.":"Nie musimy rysować każdego listka.",
"In a program we describe things with properties. A ball has a colour, a size and a speed.":"W programie opisujemy rzeczy za pomocą właściwości. Piłka ma kolor, rozmiar i prędkość.",
"So the ball is white and fast!":"Czyli piłka jest biała i szybka!",
"And a flowchart shows what happens, step by step.":"A schemat blokowy pokazuje, co się dzieje, krok po kroku.",
