"A website for Pus: HTML basics":"Strona dla Pusa: podstawy HTML",
"Nora and Leo make a website about Pus the cat. Robo explains HTML: tags in angle brackets, a heading <h1>, a paragraph <p>, an image <img> and a link <a>.":"Nora i Leo robią stronę o kocie Pusie. Robo wyjaśnia HTML: znaczniki w nawiasach ostrych, nagłówek <h1>, akapit <p>, obrazek <img> i link <a>.",
"I want to make a website about our cat, Pus!":"Chcę zrobić stronę o naszym kocie Pusie!",
"Then we need HTML.":"W takim razie potrzebujemy HTML.",
"HTML builds web pages. It is made of tags.":"HTML buduje strony internetowe. Składa się ze znaczników.",
"What is a tag?":"Co to jest znacznik?",
"A tag is a short word in angle brackets, for example p.":"Znacznik to krótkie słowo w nawiasach ostrych, na przykład p.",
"Most tags have a start and an end. The end tag has a slash.":"Większość znaczników ma początek i koniec. Znacznik zamykający ma ukośnik.",
"Like a sandwich!":"Jak kanapka!",
"I write h1 and “Pus”. It becomes a big heading!":"Piszę h1 i „Pus”. Wychodzi duży nagłówek!",
"Yes. h1 means heading number one.":"Tak. h1 oznacza nagłówek numer jeden.",
"With p we make a paragraph, and with img we show a picture.":"Za pomocą p robimy akapit, a za pomocą img pokazujemy obrazek.",
"Look, a picture of Pus!":"Patrz, zdjęcie Pusa!",
"Finally a link. The a tag takes us to another page.":"Na koniec link. Znacznik a prowadzi na inną stronę.",
"The website is ready! Next time we will make it pretty with CSS.":"Strona jest gotowa! Następnym razem upiększymy ją za pomocą CSS.",
